self.addEventListener("push",t=>{if(t.data)try{let i=t.data.json(),n={body:i.body||"New Update Available",icon:i.icon||"/icons/icon-192.png",badge:i.badge||"/icons/icon-192.png",vibrate:i.vibrate||[100,50,100],data:i.data||{url:"/dashboard/notifications"}};t.waitUntil(self.registration.showNotification(i.title||"Avior\xe8",n))}catch(n){let i=t.data.text();t.waitUntil(self.registration.showNotification("Avior\xe8 Update",{body:i}))}}),self.addEventListener("notificationclick",t=>{t.notification.close();let i=t.notification.data?.url||"/";t.waitUntil(self.clients.matchAll({type:"window",includeUncontrolled:!0}).then(t=>{for(let i of t)if("focus"in i&&"function"==typeof i.focus)return i.focus();if(self.clients.openWindow)return self.clients.openWindow(i)}))});